// Certificate pinning for controller traffic (electron/pinnedFetch.cjs +
// electron/unifiPin.cjs), exercised against real local HTTPS servers with
// throwaway self-signed certificates generated by openssl at test time.
import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import { createRequire } from 'node:module';
import { execFileSync } from 'node:child_process';
import https from 'node:https';
import http from 'node:http';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';

const require = createRequire(import.meta.url);
const { pinnedRequest, peekFingerprint } = require('../electron/pinnedFetch.cjs');
const { pinKey, loadPins, savePins, decide } = require('../electron/unifiPin.cjs');

const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'plexus-pin-'));
function selfSigned(name) {
  const key = path.join(dir, `${name}.key`), crt = path.join(dir, `${name}.crt`);
  execFileSync('openssl', ['req', '-x509', '-newkey', 'rsa:2048', '-nodes', '-keyout', key, '-out', crt, '-days', '2', '-subj', `/CN=${name}`], { stdio: 'ignore' });
  return { key: fs.readFileSync(key), cert: fs.readFileSync(crt) };
}
let haveOpenssl = true;
try { execFileSync('openssl', ['version'], { stdio: 'ignore' }); } catch { haveOpenssl = false; }

const FP_A = Array(32).fill('AA').join(':');
const FP_B = Array(32).fill('BB').join(':');

describe('pin decisions', () => {
  it('first contact asks, approval of the exact fingerprint stores, then it is used', () => {
    /** @type {Record<string,string>} */
    const pins = {};
    expect(decide(pins, 'h:443', FP_A)).toEqual({ action: 'ask-first' });
    expect(decide(pins, 'h:443', FP_A, FP_B)).toEqual({ action: 'ask-first' });   // approved a different cert
    expect(decide(pins, 'h:443', FP_A, FP_A)).toEqual({ action: 'store' });
    expect(decide({ 'h:443': FP_A }, 'h:443', FP_A)).toEqual({ action: 'use' });
  });
  it('a changed certificate is never used without a fresh approval', () => {
    const pins = { 'h:443': FP_A };
    expect(decide(pins, 'h:443', FP_B)).toEqual({ action: 'ask-changed', pinned: FP_A });
    expect(decide(pins, 'h:443', FP_B, FP_A)).toEqual({ action: 'ask-changed', pinned: FP_A });
    expect(decide(pins, 'h:443', FP_B, FP_B)).toEqual({ action: 'store' });
    expect(decide(pins, 'constructor', FP_B).action).toBe('ask-first');            // no prototype lookups
  });
  it('pins are keyed by host:port and survive a save/load, dropping junk', () => {
    expect(pinKey('https://UDM.local/x')).toBe('udm.local:443');
    expect(pinKey('https://192.0.2.1:8443')).toBe('192.0.2.1:8443');
    const file = path.join(dir, 'sub', 'pins.json');
    savePins(file, { 'a:443': FP_A });
    expect(loadPins(file)).toEqual({ 'a:443': FP_A });
    fs.writeFileSync(file, JSON.stringify({ 'a:443': FP_A, bad: 'nope', n: 5 }));
    expect(loadPins(file)).toEqual({ 'a:443': FP_A });
    expect(loadPins(path.join(dir, 'missing.json'))).toEqual({});
  });
});

describe.skipIf(!haveOpenssl)('pinned HTTPS requests', () => {
  let srvA, srvB, urlA, urlB, fpA, hits;
  const listen = (srv) => new Promise((res) => srv.listen(0, '127.0.0.1', () => res(srv.address().port)));
  beforeAll(async () => {
    hits = [];
    const handler = (tag) => (req, res) => {
      let body = '';
      req.on('data', (c) => { body += c; });
      req.on('end', () => { hits.push({ tag, method: req.method, url: req.url, body, cookie: req.headers.cookie || '' }); res.setHeader('set-cookie', 'sid=1; Path=/'); res.end(JSON.stringify({ tag })); });
    };
    srvA = https.createServer(selfSigned('controller-a'), handler('A'));
    srvB = https.createServer(selfSigned('controller-b'), handler('B'));
    urlA = `https://127.0.0.1:${await listen(srvA)}`;
    urlB = `https://127.0.0.1:${await listen(srvB)}`;
    fpA = await peekFingerprint(urlA);
  });
  afterAll(() => { srvA.close(); srvB.close(); fs.rmSync(dir, { recursive: true, force: true }); });

  it('peekFingerprint reads the certificate without speaking HTTP', async () => {
    const n = hits.length;
    expect(fpA).toMatch(/^([0-9A-F]{2}:){31}[0-9A-F]{2}$/);
    expect(await peekFingerprint(urlB)).not.toBe(fpA);
    expect(hits.length).toBe(n);
  });
  it('delivers the request when the certificate matches the pin', async () => {
    const res = await pinnedRequest(`${urlA}/api/login?x=1`, { method: 'POST', body: '{"u":"admin"}', expectedFp: fpA, headers: { Cookie: 'a=b' } });
    expect(res.status).toBe(200);
    expect(JSON.parse(res.text)).toEqual({ tag: 'A' });
    expect(res.headers['set-cookie'][0]).toMatch(/^sid=1/);
    expect(hits[hits.length - 1]).toEqual({ tag: 'A', method: 'POST', url: '/api/login?x=1', body: '{"u":"admin"}', cookie: 'a=b' });
  });
  it('sends NOTHING to a server whose certificate is not the pinned one', async () => {
    const n = hits.length;
    await expect(pinnedRequest(`${urlB}/api/login`, { method: 'POST', body: '{"password":"hunter2"}', expectedFp: fpA }))
      .rejects.toMatchObject({ code: 'CERT_CHANGED', expected: fpA });
    await new Promise((r) => setTimeout(r, 100));
    expect(hits.length).toBe(n);                 // the impostor never saw the request
  });
  it('refuses https without a pin, and rejects non-http schemes', async () => {
    await expect(pinnedRequest(`${urlA}/`, {})).rejects.toThrow(/No trusted certificate/);
    await expect(pinnedRequest('file:///etc/passwd', { expectedFp: fpA })).rejects.toThrow(/Bad controller URL/);
  });
  it('passes plain http through unpinned', async () => {
    const plain = http.createServer((req, res) => res.end('ok'));
    const port = await listen(plain);
    const res = await pinnedRequest(`http://127.0.0.1:${port}/`, {});
    plain.close();
    expect(res).toMatchObject({ status: 200, text: 'ok', fingerprint: null });
    expect(await peekFingerprint(`http://127.0.0.1:${port}/`)).toBeNull();
  });
});
